// One-off generator: mirrors editorial-intelligence.mjs (the canonical
// shared source, Phase 1 of EDITORIAL_INTELLIGENCE_ENGINE.md) into
// shared/editorial-intelligence.js, a plain non-module <script> the browser
// tools load directly — same pattern as gen-flavour-engine-browser.mjs.
// Re-run this any time editorial-intelligence.mjs changes; do not hand-edit
// the generated file.
//
// Deliberately mirrors ONLY editorial-intelligence.mjs (Phase 1 — pure JS,
// zero imports, no Node-specific API). The later phases (rag-evidence.mjs,
// topic-state.mjs, editorial-genome.mjs, editorial-brief.mjs) depend on
// Automation/ncert-knowledge-base/retrieve.mjs, which imports node:fs
// directly and cannot run in a browser without being ported to a
// fetch-based index loader first — that is a real architecture decision,
// not something this generator should paper over. See
// notes-factory/index.html's buildEditorialSignatureBlock() for where this
// boundary is documented at the call site.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(__dirname, '..', '..', '..');
const src = fs.readFileSync(path.join(__dirname, 'editorial-intelligence.mjs'), 'utf8');

// Strip `export ` keywords (the only ESM-specific syntax this file uses) —
// everything else is plain JS, safe to run as-is in a non-module <script>.
const body = src.replace(/^export /gm, '');

const out = `// AUTO-GENERATED by gen-editorial-intelligence-browser.mjs from
// Automation/core/src/editorial-intelligence.mjs. Do not hand-edit — re-run
// the generator instead so this never drifts from the canonical source.
// Exposes window.EditorialIntelligence = { buildEditorialSignature, extractCardSentences }.
// NOTE: this mirrors Phase 1 ONLY (pure, no node:fs dependency). Phases
// 4/6/7/8 (RAG evidence, topic state, genome, brief) are NOT included here
// because they transitively depend on retrieve.mjs's node:fs usage — see
// this generator's header comment.
(function(global){
${body}
global.EditorialIntelligence = { buildEditorialSignature, extractCardSentences };
})(typeof window !== 'undefined' ? window : this);
`;

const outDir = path.join(REPO_ROOT, 'shared');
fs.mkdirSync(outDir, { recursive: true });
fs.writeFileSync(path.join(outDir, 'editorial-intelligence.js'), out);
console.log('wrote shared/editorial-intelligence.js');
